    lines = text.strip().split('\n')
    return [[int(x) for x in line.split()] for line in lines]

def generate_pattern(C):
    return [
        [0, C, C, 0],
        [0, 0, C, 0],
        [C, C, C, C],
        [0, C, 0, 0]
    ]

def transform(grid):
    h = len(grid)
    w = len(grid[0])

    sep_rows = [r for r in range(h) if all(grid[r][c] == grid[r][0] and grid[r][0] != 0 for c in range(w))]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] and grid[0][c] != 0 for r in range(h))]
    block_size = 4

    # Compute block starts
    r_starts = []
    if not sep_rows:
        r_starts = [0]
    else:
        curr = 0
        for s in sep_rows:
            if s - curr >= block_size:
                r_starts.append(curr)
                curr = s + 1
        if h - curr >= block_size:
            r_starts.append(curr)

    c_starts = []
    if not sep_cols:
        c_starts = [0]
    else:
        curr = 0
        for s in sep_cols:
            if s - curr >= block_size:
                c_starts.append(curr)
                curr = s + 1
        if w - curr >= block_size:
            c_starts.append(curr)

    # Start with a copy (preserves input and separators)
    result = [row[:] for row in grid]

    # First pass: determine color for each row section
    block_row_colors = {}
    for r_idx, r_start in enumerate(r_starts):
        colors = []
        for rr in range(r_start, min(r_start + block_size, h)):
            for cc in range(c_starts[0], min(c_starts[0] + block_size, w)):
                val = grid[rr][cc]
                if val != 0 and val not in block_row_colors:
                    colors.append(val)

        if colors:
            # Take the first non-zero color found in this row section
            block_row_colors[r_idx] = colors[0]
        else:
            block_row_colors[r_idx] = 0

    print(f"Row colors: {block_row_colors}")

    def has_content(block_start):
        for rr in range(block_start, min(block_start + block_size, h)):
            for cc in range(block_start, min(block_start + block_size, w)):
                val = grid[rr][cc]
                if val != 0 and val not in [ grid[sep_row][cc] for sep_row in sep_rows ]:
                    return True
        return False

    # Actually simpler: just check if any cell (not separator row) is non-zero
    def find_block_content_color(r_start, c_start):
        colors_found = set()
        for rr in range(r_start, min(r_start + block_size, h)):
            for cc in range(c_start, min(c_start + block_size, w)):
                val = grid[rr][cc]
                if val != 0:
                    colors_found.add(val)
        return list(colors_found) if colors_found else []

    # Second pass: for each block, apply pattern with ROW color
    for r_idx, r_start in enumerate(r_starts):
        row_color = block_row_colors[r_idx]
        for c_idx, c_start in enumerate(c_starts):
            # Apply pattern for THIS block using the row's color
            if row_color == 0:
                continue  # Skip if no row color

            pat = generate_pattern(row_color)
            for pr in range(4):
